sysauto_script.script:
(function() {
    var uniqueGroups = [];
    var dailyReviewGR = new GlideRecordSecure('x_enno_gatenow_grant_review'); 


    dailyReviewGR.addEncodedQuery('review_start_dateONToday@javascript:gs.beginningOfToday()@javascript:gs.endOfToday()');
    dailyReviewGR.query();

    while (dailyReviewGR.next()) {
        var groupsInList = dailyReviewGR.getValue('reviewer');


        if (!groupsInList) continue; 

        var groupsArray = groupsInList.split(',');
        for (var i = 0; i < groupsArray.length; i++) {
            var groupId = groupsArray[i].trim();


            if (groupId && uniqueGroups.indexOf(groupId) === -1) {
                uniqueGroups.push(groupId);
            }
        }
    }


    if (uniqueGroups.length > 0) {
        var userGroupGR = new GlideRecord('sys_user_group');
        userGroupGR.addQuery('sys_id', 'IN', uniqueGroups.join(','));
        userGroupGR.query();

        while (userGroupGR.next()) {

            gs.eventQueue('x_enno_gatenow.group.daily_review', userGroupGR, userGroupGR.getUniqueValue(), ''); 
        }
    }
})();
